-- Hosbah: a persistent volume of a git-deployed site (app). The Docker volume's name is derived
-- (hosbah-vol-<app id>-<name>; cloudy-vol-… when made before the rename), never stored or user-supplied. mount_path is an absolute, cleaned
-- path inside the containers; the deploy pipeline hands the app's volumes to the agent, which mounts
-- them into the web and every worker container of a release. A volume applies from the next deploy,
-- restart or rollback. The system roots (/proc, /etc, …) and parent/child overlaps are refused by
-- internal/storage (and again by the agent). Rows go with their app; the Docker volume does not.
ALTER TABLE app_volumes ADD CONSTRAINT app_volumes_name_check CHECK (name ~ '^[a-z][a-z0-9-]{0,30}$');
ALTER TABLE app_volumes ADD CONSTRAINT app_volumes_mount_path_check CHECK (length(mount_path) BETWEEN 2 AND 200 AND mount_path ~ '^/[A-Za-z0-9._/-]*$');
CREATE UNIQUE INDEX app_volumes_app_name_key ON app_volumes (app_id, name);
CREATE UNIQUE INDEX app_volumes_app_mount_path_key ON app_volumes (app_id, mount_path);
CREATE UNIQUE INDEX app_volumes_id_team_key ON app_volumes (id, team_id);
CREATE INDEX app_volumes_team_idx ON app_volumes (team_id);
